; score.asm -- chapter 9: a score in BCD and in binary
; generated by gen09.py
        INCLUDE "msx.inc"
        OUTPUT "score.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
row     EQU RAM_START + $10     ; the row to print on
score   EQU RAM_START + $11     ; six BCD digits, the first two first
total   EQU RAM_START + $14     ; the same points in binary
txt     EQU RAM_START + $16     ; six characters and a 0
txt2    EQU RAM_START + $1D     ; five characters and a 0
; 37 points a frame, added to a score of six BCD digits and to a binary
; total, each turned into digits and printed on the next row: the BCD score,
; the binary total in hexadecimal, and the binary total in decimal (figure
; 9.2). The display stays off while the frames go by, and comes on at the end.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 1
        ld hl, h0
        call puts
        ld b, 0
        ld c, 10
        ld hl, h1
        call puts
        ld b, 0
        ld c, 17
        ld hl, h2
        call puts
        xor a
        ld (score), a
        ld (score + 1), a
        ld (score + 2), a
        ld (txt + 6), a
        ld (txt2 + 5), a        ; the ends of the two texts
        ld h, a
        ld l, a
        ld (total), hl
        ld a, 2
        ld (row), a
        VDP_REG 1, $A0          ; display still off, frame interrupt on
        im 1
        ei
frame:  halt                    ; one frame, 37 points (C-BIOS's routine runs)
bcdsum: ld hl, score + 2        ; the last two digits
        ld a, (hl)
        add a, $37              ; 37 points, written in BCD
        daa                     ; two decimal digits again, and a carry
        ld (hl), a
        dec hl                  ; DEC of a pair keeps the carry
        ld a, (hl)
        adc a, 0                ; the carry into the next two digits
        daa
        ld (hl), a
        dec hl
        ld a, (hl)
        adc a, 0                ; and into the first two
        daa
        ld (hl), a
binsum: ld hl, (total)
        ld de, 37
        add hl, de
        ld (total), hl          ; the same points, counted in binary
t1:     call bcdtxt             ; the BCD score as text
t2:     call bintxt             ; the binary total as text
t3:     ld a, (row)
        ld b, a
        ld c, 1
        ld hl, txt
        call puts
        ld c, 10
        ld a, (total + 1)
        call puthex
        ld a, (total)
        call puthex
        ld c, 17
        ld hl, txt2
        call puts
        ld a, (row)
        inc a
        ld (row), a
        cp 22
        jr nz, frame
        di
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; bcdtxt: the six BCD digits at score, into six characters at txt. Each
;         digit is four bits of a byte: no arithmetic at all.
bcdtxt: ld hl, score
        ld de, txt
        ld b, 3
bt1:    ld a, (hl)
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        and %00001111
        add a, '0'
        ld (de), a
        inc de
        ld a, (hl)
        and %00001111           ; then the low four bits
        add a, '0'
        ld (de), a
        inc de
        inc hl
        djnz bt1
        ret

; bintxt: the binary total (0-65535) into five characters at txt2, by
;         counting how many times each power of ten goes into it
bintxt: ld hl, (total)
        ld de, txt2
        ld bc, -10000
        call digit
        ld bc, -1000
        call digit
        ld bc, -100
        call digit
        ld bc, -10
        call digit
        ld a, l                 ; what is left is the last digit
        add a, '0'
        ld (de), a
        ret
digit:  ld a, '0' - 1
dg1:    inc a
        add hl, bc              ; take the power of ten away once more ...
        jr c, dg1               ; ... as long as it went
        sbc hl, bc              ; one time too many: put it back
        ld (de), a
        inc de
        ret

h0:     db "BCD", 0
h1:     db "HEX", 0
h2:     db "DECIMAL", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
